def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start with absolute path or relative to cwd
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split path into components
    components = remaining.split('/') if remaining else []

    link_count = 0

    while True:
        # Process components one by one
        processed = False

        for i, component in enumerate(components):
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                next_path = '/' + component
            else:
                next_path = current + '/' + component

            # Check if this path is a symlink
            if next_path in links:
                link_count += 1
                if link_count > 8:
                    return None

                # Get the link target
                target = links[next_path]

                # Resolve remaining components and link target together
                remaining_components = components[i+1:]

                if target.startswith('/'):
                    current = '/'
                    target_components = target[1:].split('/') if target[1:] else []
                else:
                    # Target is relative to the directory containing the link
                    if next_path == '/':
                        base = '/'
                    else:
                        base = next_path.rsplit('/', 1)[0]
                    if not base:
                        base = '/'
                    current = base
                    target_components = target.split('/') if target else []

                # Combine target components with remaining components
                components = [c for c in target_components + remaining_components if c]
                processed = True
                break
            else:
                current = next_path

        if not processed:
            break

    # Remove trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

